def bootstrap_ci(values, resample, n_boot=1000, ci=95):
    if not values:
        raise ValueError("no observations to summarise")
    if n_boot < 1:
        raise ValueError("n_boot must be at least 1")
    if not 0 < ci < 100:
        raise ValueError("ci must be strictly between 0 and 100")
    estimate = sum(values) / len(values)
    means = []
    for i in range(n_boot):
        draw = resample(values, i)
        if len(draw) != len(values):
            raise ValueError("a resample must be the same size as the sample")
        means.append(sum(draw) / len(draw))
    means.sort()
    tail = (100 - ci) / 2 / 100
    def pick(q):
        index = int(round(q * (n_boot - 1)))
        return means[max(0, min(n_boot - 1, index))]
    return {"estimate": estimate, "low": pick(tail), "high": pick(1 - tail)}
